def seed_all(db, ClassLevel, Subject, Chapter, Question):
    if ClassLevel.query.first():
        return  # already seeded
    cls_map, subj_map, ch_map = {}, {}, {}
    for i, name in enumerate(CLASSES):
        c = ClassLevel(name=name, sort_order=i + 1)
        db.session.add(c)
        db.session.flush()
        cls_map[name] = c.id
        for sname in SUBJECTS:
            s = Subject(name=sname, class_level_id=c.id)
            db.session.add(s)
            db.session.flush()
            subj_map[(name, sname)] = s.id
            for n, chname in enumerate(CHAPTERS.get((name, sname), []), start=1):
                ch = Chapter(name=chname, number=n, subject_id=s.id)
                db.session.add(ch)
                db.session.flush()
                ch_map[(name, sname, n)] = ch.id
    db.session.commit()
    for (cls, subj, chno, qtype, source, diff, text, opts, correct, answer, marks) in Q:
        db.session.add(Question(
            class_level_id=cls_map[cls], subject_id=subj_map[(cls, subj)],
            chapter_id=ch_map[(cls, subj, chno)], qtype=qtype, source=source,
            difficulty=diff, text=text,
            options_json=json.dumps(opts) if opts else None,
            correct_option=correct, answer=answer, marks=marks))
    db.session.commit()
